import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.CyZTVJbV.js";const k=JSON.parse('{"title":"Migration guide — v1.15 → v1.16","description":"","frontmatter":{},"headers":[],"relativePath":"migrations/v1.15-to-v1.16.md","filePath":"migrations/v1.15-to-v1.16.md"}'),s={name:"migrations/v1.15-to-v1.16.md"};function r(n,e,c,d,l,h){return i(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="migration-guide-—-v1-15-→-v1-16" tabindex="-1">Migration guide — v1.15 → v1.16 <a class="header-anchor" href="#migration-guide-—-v1-15-→-v1-16" aria-label="Permalink to &quot;Migration guide — v1.15 → v1.16&quot;">​</a></h1><p>v1.16 is <strong>additive</strong> — every <code>@kiwa-lab/*</code> package that existed in v1.15 keeps its public API. Existing tests keep passing.</p><p>The 3 things v1.16 adds are:</p><ul><li><code>@kiwa-lab/component</code> v0.1 (new package, unified Storybook 8 + Playwright Component Testing + Chromatic mock harness)</li><li>3 dogfood apps (<code>dogfood-storybook-design-system</code> + <code>dogfood-form-ct</code> + <code>dogfood-visual-regression</code>) that measure the mock against real Storybook / Playwright CT / Chromatic surfaces</li><li>3 tutorials, 1 concept doc, 1 migration guide (this file) covering component test setup</li></ul><h2 id="what-breaks-nothing" tabindex="-1">What breaks (nothing) <a class="header-anchor" href="#what-breaks-nothing" aria-label="Permalink to &quot;What breaks (nothing)&quot;">​</a></h2><p>Nothing. The v1.16 changes are pure additions.</p><ul><li><code>@kiwa-lab/ai-llm</code> / <code>@kiwa-lab/mcp</code> / <code>@kiwa-lab/agent</code> / <code>@kiwa-lab/realtime</code> / <code>@kiwa-lab/perf-harness</code> / <code>@kiwa-lab/quality-metrics</code> — unchanged.</li><li><code>evaluateReleaseGate</code> — same 11-axis contract as v1.15. Component providers (<code>@kiwa-lab/component/*</code> prefix) roll into the common 7-axis branch (coverage / test count / fidelity / perf p95 / mutation). The AI-LLM 4 axes (cost / latency / token / accuracy) do not apply to a rendering surface.</li><li>Everything else (auth / queue / cache / realtime / payment / search / observability / polyglot Rust + Go / dApp / framework adapters / docs skills) — untouched.</li></ul><h2 id="what-s-new-opt-in" tabindex="-1">What&#39;s new (opt in) <a class="header-anchor" href="#what-s-new-opt-in" aria-label="Permalink to &quot;What&#39;s new (opt in)&quot;">​</a></h2><h3 id="kiwa-lab-component-v0-1-—-3-integration-unified-mock" tabindex="-1"><code>@kiwa-lab/component</code> v0.1 — 3 integration unified mock <a class="header-anchor" href="#kiwa-lab-component-v0-1-—-3-integration-unified-mock" aria-label="Permalink to &quot;\`@kiwa-lab/component\` v0.1 — 3 integration unified mock&quot;">​</a></h3><p>New dependency:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa-lab/component</span></span></code></pre></div><p>Three factories, one shared DOM primitive layer, framework agnostic (React / Vue / Svelte / Solid render as <code>(args) =&gt; MockNode</code>).</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  createChromaticVisualMock,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  createPlaywrightCTMock,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  createStoryRegistry,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@kiwa-lab/component&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> registry</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createStoryRegistry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ct</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createPlaywrightCTMock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> chromatic</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createChromaticVisualMock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ defaultDiffThreshold: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span></code></pre></div><p>The 3 mocks share the same underlying <code>MockNode</code> tree so the same <code>render(args)</code> function feeds all 3 surfaces without adapters in between.</p><ul><li><code>createStoryRegistry()</code> — Storybook 8 CSF3 compatible in-memory registry with <code>register</code> + <code>list</code> + <code>mount</code> + <code>play</code> + <code>runA11y</code></li><li><code>createPlaywrightCTMock()</code> — Playwright Component Testing shaped <code>mount(render, args) → locator</code> with <code>getByRole</code> + <code>getByText</code> + <code>click</code> + <code>fill</code></li><li><code>createChromaticVisualMock(config)</code> — baseline / current / diff / accept / reject workflow keyed on SHA-256 markup hashes</li></ul><p>Config knobs (all optional; safe defaults keep the primary code paths passing).</p><ul><li><code>ChromaticConfig.defaultViewport</code> — default <code>&#39;default&#39;</code>, used when a story does not set <code>parameters.chromatic.viewports</code></li><li><code>ChromaticConfig.defaultDiffThreshold</code> — default <code>0</code> (hash-exact matching)</li><li><code>ChromaticConfig.now</code> — deterministic time source for <code>capturedAt</code> / <code>reviewedAt</code>, used to make test outputs stable</li></ul><p>The 5 built-in fixtures (<code>buildButton</code> / <code>buildInput</code> / <code>buildForm</code> / <code>buildModal</code> / <code>buildCard</code>) are opt-in — production code registers its own <code>render</code> functions and never has to import from <code>fixture.js</code>.</p><h3 id="dogfood-apps-3-new-all-opt-in" tabindex="-1">Dogfood apps (3 new, all opt in) <a class="header-anchor" href="#dogfood-apps-3-new-all-opt-in" aria-label="Permalink to &quot;Dogfood apps (3 new, all opt in)&quot;">​</a></h3><p>Three examples ship under <code>examples/</code>, each producing a real vs mock fidelity report that feeds the 7-axis release gate.</p><ul><li><code>dogfood-storybook-design-system</code> — 12 React primitives (Button / Input / Card / Modal / Dropdown / Tabs / Toast / Table / Tooltip / Badge / Avatar / Icon) registered as <code>StoryObj</code> with <code>args</code> + <code>play</code> + a11y checks. Real adapter env-gates on <code>STORYBOOK_URL</code>.</li><li><code>dogfood-form-ct</code> — 5 form patterns (login / signup / checkout / profile / search) driven through the Playwright CT mock with 4 assertions each (mount / validation / submit / a11y). Real adapter env-gates on <code>PW_CT_ENDPOINT</code>.</li><li><code>dogfood-visual-regression</code> — 10 UI scenes (5 primitives × light / dark) covering the 4 AC axes (baseline seed / capture / diff-on-intent-change / accept-restores-baseline). Real adapter env-gates on <code>CHROMATIC_PROJECT_TOKEN</code>.</li></ul><p>Every dogfood app writes its fidelity report to <code>quality-report/fidelity-latest.md</code> (git-ignored) and to <code>docs/quality-reports/component/&lt;name&gt;.md</code> (git-tracked snapshot promoted per release).</p><h2 id="release-gate" tabindex="-1">Release gate <a class="header-anchor" href="#release-gate" aria-label="Permalink to &quot;Release gate&quot;">​</a></h2><p>The 11-axis contract is unchanged. Component providers keep their prefix routed to the 7-axis common branch (coverage 3 / fidelity / perf p95 / mutation / behavior tests). The AI-LLM 4 axes (cost / latency / token / accuracy) route only through providers whose name starts with <code>@kiwa-lab/ai-</code> (see <code>isAiLlmProvider</code> in <code>packages/quality-metrics/src/types.ts</code>) — component surfaces are excluded because there is no token pricing to measure.</p><p>The component thresholds match the common 7-axis defaults documented in v1.15 — line coverage ≥ 85%, branch ≥ 80%, function ≥ 90%, fidelity ratio ≥ 70%, perf p95 ≤ 100 ms for mount + play + a11y, mutation kill rate ≥ 60%, behavior test count ≥ 10.</p><h2 id="upgrade-checklist" tabindex="-1">Upgrade checklist <a class="header-anchor" href="#upgrade-checklist" aria-label="Permalink to &quot;Upgrade checklist&quot;">​</a></h2><ul><li>[ ] <code>pnpm add -D @kiwa-lab/component</code> at each package that wants Storybook / CT / Chromatic mocks</li><li>[ ] Copy the fixture pattern from <code>examples/dogfood-storybook-design-system/src/components/design-system.ts</code> for framework-agnostic renderers</li><li>[ ] Wire <code>runFidelityCheck</code> in your test setup to emit a report for the release gate</li><li>[ ] Register your Storybook <code>.stories.ts</code> files with <code>registry.register(meta)</code> — CSF3 <code>meta.args</code> + <code>story.args</code> merge automatically</li><li>[ ] Set <code>parameters.chromatic.viewports</code> when a story needs multiple viewports (mobile / desktop) captured</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="./../tutorials/19-storybook-design-system">Tutorial 19 — Storybook 8 design system in 12 min</a></li><li><a href="./../tutorials/20-playwright-ct">Tutorial 20 — Playwright CT for 5 form patterns in 12 min</a></li><li><a href="./../tutorials/21-visual-regression">Tutorial 21 — Visual regression baseline / diff / accept in 12 min</a></li><li><a href="./../concepts/component-testing">Concept — Component testing (story + CT + visual diff)</a></li><li>v1.16 milestone parent <a href="https://github.com/cardene777/kiwa/issues/762" target="_blank" rel="noreferrer">#762</a>, sub-issues <a href="https://github.com/cardene777/kiwa/issues/763" target="_blank" rel="noreferrer">#763</a> / <a href="https://github.com/cardene777/kiwa/issues/764" target="_blank" rel="noreferrer">#764</a> / <a href="https://github.com/cardene777/kiwa/issues/765" target="_blank" rel="noreferrer">#765</a> / <a href="https://github.com/cardene777/kiwa/issues/766" target="_blank" rel="noreferrer">#766</a> / <a href="https://github.com/cardene777/kiwa/issues/767" target="_blank" rel="noreferrer">#767</a></li></ul>`,29)])])}const g=a(s,[["render",r]]);export{k as __pageData,g as default};
